1	import { useEffect, useMemo, useState } from 'react';
2	import { printHTML } from '@/shared/lib/print';
3	import {
4	  Dialog,
5	  DialogContent,
6	  DialogDescription,
7	  DialogHeader,
8	  DialogTitle,
9	} from '@/shared/ui/dialog';
10	import {
11	  Card,
12	  CardContent,
13	  CardHeader,
14	  CardTitle,
15	  CardDescription,
16	} from '@/shared/ui/card';
17	import {
18	  Table,
19	  TableBody,
20	  TableCell,
21	  TableHead,
22	  TableHeader,
23	  TableRow,
24	} from '@/shared/ui/table';
25	import { Button } from '@/shared/ui/button';
26	import { Badge } from '@/shared/ui/badge';
27	import { Printer, X } from 'lucide-react';
28	import { supabase } from '@/integrations/supabase/client';
29	import { useIsMobile } from '@/shared/hooks/use-mobile';
30	import { getStoreLabel } from '@/shared/ui/StoreSelector';
31	
32	interface RequisicaoRow {
33	  id: number;
34	  nome: string;
35	  solicitante: string;
36	  loja_solicitante: string;
37	  loja_preparadora: string;
38	  data_pedido: string; // DATE ISO (yyyy-mm-dd)
39	  data_recebimento: string | null; // DATE ISO
40	  created_at: string;
41	  subtitle?: string;
42	}
43	
44	interface RequisicaoItemRow {
45	  id: number;
46	  nome_produto: string;
47	  quantidade_solicitada: number;
48	  quantidade_enviada: string | null;
49	  observacao: string | null;
50	  ordem: number | null;
51	  lote: string | null;
52	  validade: string | null;
53	}
54	
55	interface Props {
56	  isOpen: boolean;
57	  onClose: () => void;
58	  requisicao: RequisicaoRow | null;
59	}
60	
61	const parseNumber = (value?: string | null) => {
62	  if (!value) return 0;
63	  const m = value.match(/[0-9]+([.,][0-9]+)?/);
64	  if (!m) return 0;
65	  const n = parseFloat(m[0].replace(',', '.'));
66	  return isNaN(n) ? 0 : n;
67	};
68	
69	export const RequisicaoDetailsModal = ({
70	  isOpen,
71	  onClose,
72	  requisicao,
73	}: Props) => {
74	  const isMobile = useIsMobile();
75	  const [loading, setLoading] = useState(false);
76	  const [itens, setItens] = useState<RequisicaoItemRow[]>([]);
77	
78	  useEffect(() => {
79	    const load = async () => {
80	      if (!isOpen || !requisicao) return;
81	      setLoading(true);
82	      const { data, error } = await supabase
83	        .from('requisicoes_itens')
84	        .select(
85	          'id, nome_produto, quantidade_solicitada, quantidade_enviada, observacao, ordem, lote, validade',
86	        )
87	        .eq('requisicao_id', requisicao.id)
88	        .order('ordem', { ascending: true });
89	      if (!error) setItens((data || []) as RequisicaoItemRow[]);
90	      setLoading(false);
91	    };
92	    load();
93	    // eslint-disable-next-line react-hooks/exhaustive-deps
94	  }, [isOpen, requisicao?.id]);
95	
96	  const totalPedida = useMemo(
97	    () =>
98	      itens.reduce(
99	        (acc, it) => acc + (Number(it.quantidade_solicitada) || 0),
100	        0,
101	      ),
102	    [itens],
103	  );
104	  const totalEntregue = useMemo(
105	    () =>
106	      itens.reduce((acc, it) => acc + parseNumber(it.quantidade_enviada), 0),
107	    [itens],
108	  );
109	
110	  const formatDateBR = (iso?: string | null) => {
111	    if (!iso) return '-';
112	    const [y, m, d] = iso.split('-');
113	    return `${d}/${m}/${y}`;
114	  };
115	
116	  const printSelected = () => {
117	    if (!requisicao) return;
118	
119	    const orderDateFormatted = formatDateBR(requisicao.data_pedido);
120	    const receivedDateFormatted = formatDateBR(requisicao.data_recebimento);
121	
122	    const printContent = `
123	      <!DOCTYPE html>
124	      <html>
125	      <head>
126	        <title>Requisição Fábrica</title>
127	        <style>
128	          @page { margin: 15mm; size: A4; }
129	          * { margin: 0; padding: 0; box-sizing: border-box; }
130	          body { font-family: Arial, sans-serif; font-size: 11px; line-height: 1.2; }
131	          .header { background-color: #4CAF50; color: white; text-align: center; padding: 8px; font-weight: bold; font-size: 14px; }
132	          .header-title { letter-spacing: 0.5px; }
133	          .info-section { border: 1px solid #333; border-top: none; }
134	          .info-row { display: flex; border-bottom: 1px solid #333; min-height: 25px; }
135	          .info-row:last-child { border-bottom: none; }
136	          .info-cell { padding: 4px 8px; border-right: 1px solid #333; display: flex; align-items: center; background-color: #f5f5f5; }
137	          .info-cell:last-child { border-right: none; }
138	          .info-cell.value { background-color: white; font-weight: bold; }
139	          .products-header { background-color: #4CAF50; color: white; display: flex; font-weight: bold; border: 1px solid #333; margin-top: 10px; }
140	          .products-header div { padding: 6px 4px; border-right: 1px solid #333; text-align: center; font-size: 10px; }
141	          .products-header div:last-child { border-right: none; }
142	          .product-row { display: flex; border: 1px solid #333; border-top: none; min-height: 22px; }
143	          .product-cell { padding: 3px 6px; border-right: 1px solid #333; display: flex; align-items: center; font-size: 10px; }
144	          .product-cell:last-child { border-right: none; }
145	          .product-name { flex: 2; text-transform: uppercase; font-weight: bold; }
146	          .quantity-cell { flex: 0.6; text-align: center; justify-content: center; }
147	          .obs-cell { flex: 1.5; }
148	          .check-cell { flex: 0.6; text-align: center; justify-content: center; }
149	          @media print { body { -webkit-print-color-adjust: exact; } }
150	        </style>
151	      </head>
152	      <body>
153	        <div class="header">
154	          <span class="header-title">MOMMA DOCES SAUDÁVEIS</span>
155	          ${requisicao.subtitle ? `<br/><span style="font-size: 12px; font-weight: normal;">${requisicao.subtitle}</span>` : ''}
156	        </div>
157	        <div class="info-section">
158	          <div class="info-row">
159	            <div class="info-cell" style="flex: 1;">SOLICITANTE:</div>
160	            <div class="info-cell value" style="flex: 1;">${requisicao.solicitante || ''}</div>
161	            
162	          </div>
163	          <div class="info-row">
164	            <div class="info-cell" style="flex: 1;">LOJA SOLICITANTE:</div>
165	            <div class="info-cell value" style="flex: 1;">${getStoreLabel(requisicao.loja_solicitante)}</div>
166	            <div class="info-cell" style="flex: 1;">LOCAL DE PREPARO:</div>
167	            <div class="info-cell value" style="flex: 1;">Fábrica</div>
168	          </div>
169	          <div class="info-row">
170	            <div class="info-cell" style="flex: 1;">DATA DO PEDIDO:</div>
171	            <div class="info-cell value" style="flex: 1;">${orderDateFormatted}</div>
172	            <div class="info-cell" style="flex: 1;">DATA RECEBIDO:</div>
173	            <div class="info-cell value" style="flex: 1;">${receivedDateFormatted}</div>
174	          </div>
175	        </div>
176	        <div class="products-header">
177	          <div class="product-name">PRODUTOS</div>
178	          <div class="quantity-cell">QUANT PEDIDOS</div>
179	          <div class="quantity-cell">QUANT ENTREGUE</div>
180	          <div class="obs-cell">SITUAÇÃO DO PEDIDO</div>
181	          <div class="quantity-cell">LOTE</div>
182	          <div class="quantity-cell">VAL.</div>
183	          <div class="obs-cell">OBSERVAÇÕES</div>
184	        </div>
185	        ${itens
186	          .map(
187	            (it) => `
188	          <div class="product-row">
189	            <div class="product-cell product-name">${(it.nome_produto || '').toUpperCase()}</div>
190	            <div class="product-cell quantity-cell">${it.quantidade_solicitada ?? ''}</div>
191	            <div class="product-cell quantity-cell">${it.quantidade_enviada ?? ''}</div>
192	            <div class="product-cell obs-cell"></div>
193	            <div class="product-cell quantity-cell">${it.lote || ''}</div>
194	            <div class="product-cell quantity-cell">${it.validade || ''}</div>
195	            <div class="product-cell obs-cell">${it.observacao ?? ''}</div>
196	          </div>
197	        `,
198	          )
199	          .join('')}
200	      </body>
201	      </html>
202	    `;
203	
204	    printHTML(printContent, { title: `Requisição Fábrica` });
205	  };
206	
207	  return (
208	    <Dialog open={isOpen} onOpenChange={onClose}>
209	      <DialogContent data-mia-modal="detalhes-da-requisi-o"
210	        className={`${isMobile ? 'w-[95vw] h-[95vh] max-w-none max-h-none p-3' : 'sm:max-w-5xl max-h-[90vh]'} overflow-y-auto`}
211	      >
212	        <DialogHeader className={isMobile ? 'pb-2' : ''}>
213	          <DialogTitle
214	            className={`flex items-center justify-between ${isMobile ? 'text-lg' : ''}`}
215	          >
216	            <div className="flex items-center gap-2 min-w-0">
217	              <span className={`${isMobile ? 'text-sm' : ''} truncate`}>
218	                Detalhes da Requisição
219	              </span>
220	            </div>
221	            <Button data-mia-action="on-close"
222	              variant="ghost"
223	              size={isMobile ? 'sm' : 'sm'}
224	              onClick={onClose}
225	              className="flex-shrink-0"
226	            >
227	              <X className="h-4 w-4" />
228	            </Button>
229	          </DialogTitle>
230	          {!isMobile && (
231	            <DialogDescription>
232	              Itens, quantidades pedidas e entregues
233	            </DialogDescription>
234	          )}
235	        </DialogHeader>
236	
237	        {requisicao && (
238	          <div className="space-y-4">
239	            <Card>
240	              <CardHeader className={isMobile ? 'pb-2' : 'pb-4'}>
241	                <CardTitle className="flex flex-col gap-1">
242	                  <div className="flex items-center gap-2">
243	                    <span className="truncate">{requisicao.nome}</span>
244	                  </div>
245	                  {requisicao.subtitle && (
246	                    <div className="text-sm font-normal text-muted-foreground">
247	                      {requisicao.subtitle}
248	                    </div>
249	                  )}
250	                </CardTitle>
251	                <CardDescription>
252	                  <div
253	                    className={`grid ${isMobile ? 'grid-cols-1 gap-1' : 'grid-cols-2 gap-2'}`}
254	                  >
255	                    <div>
256	                      <span className="text-muted-foreground">Loja:</span>{' '}
257	                      {getStoreLabel(requisicao.loja_solicitante)}
258	                    </div>
259	                    <div>
260	                      <span className="text-muted-foreground">
261	                        Solicitante:
262	                      </span>{' '}
263	                      {requisicao.solicitante || '-'}
264	                    </div>
265	                    <div>
266	                      <span className="text-muted-foreground">Pedido:</span>{' '}
267	                      {formatDateBR(requisicao.data_pedido)}
268	                    </div>
269	                    <div>
270	                      <span className="text-muted-foreground">Recebido:</span>{' '}
271	                      {formatDateBR(requisicao.data_recebimento)}
272	                    </div>
273	                  </div>
274	                </CardDescription>
275	              </CardHeader>
276	              <CardContent>
277	                <div
278	                  className={`flex ${isMobile ? 'flex-col gap-2' : 'items-center justify-between'}`}
279	                >
280	                  <div className="flex items-center gap-2">
281	                    <Badge variant="outline">Itens: {itens.length}</Badge>
282	                    <Badge variant="outline">Total Pedida: {totalPedida}</Badge>
283	                    <Badge variant="outline">
284	                      Total Entregue: {totalEntregue}
285	                    </Badge>
286	                  </div>
287	                  <div className="flex items-center gap-2">
288	                    <Button data-mia-action="print-selected"
289	                      size={isMobile ? 'sm' : 'sm'}
290	                      onClick={printSelected}
291	                      className="gap-2"
292	                    >
293	                      <Printer className="h-4 w-4" />
294	                      Exportar PDF
295	                    </Button>
296	                  </div>
297	                </div>
298	
299	                <div
300	                  className={
301	                    isMobile ? 'overflow-x-auto -mx-2 px-2 mt-3' : 'mt-4'
302	                  }
303	                >
304	                  <Table className={isMobile ? 'min-w-[520px] text-xs' : ''}>
305	                    <TableHeader>
306	                      <TableRow>
307	                        <TableHead
308	                          className={isMobile ? 'text-xs p-1 w-[220px]' : ''}
309	                        >
310	                          Produto
311	                        </TableHead>
312	                        <TableHead
313	                          className={isMobile ? 'text-xs p-1 w-[80px]' : ''}
314	                        >
315	                          Lote
316	                        </TableHead>
317	                        <TableHead
318	                          className={isMobile ? 'text-xs p-1 w-[80px]' : ''}
319	                        >
320	                          Validade
321	                        </TableHead>
322	                        <TableHead
323	                          className={isMobile ? 'text-xs p-1 w-[70px]' : ''}
324	                        >
325	                          Qnt Pedida
326	                        </TableHead>
327	                        <TableHead
328	                          className={isMobile ? 'text-xs p-1 w-[90px]' : ''}
329	                        >
330	                          Qnt Entregue
331	                        </TableHead>
332	                        <TableHead className={isMobile ? 'text-xs p-1' : ''}>
333	                          Observação
334	                        </TableHead>
335	                      </TableRow>
336	                    </TableHeader>
337	                    <TableBody>
338	                      {loading ? (
339	                        <TableRow>
340	                          <TableCell colSpan={6} className="text-center">
341	                            Carregando...
342	                          </TableCell>
343	                        </TableRow>
344	                      ) : itens.length === 0 ? (
345	                        <TableRow>
346	                          <TableCell
347	                            colSpan={6}
348	                            className="text-center text-muted-foreground"
349	                          >
350	                            Nenhum item
351	                          </TableCell>
352	                        </TableRow>
353	                      ) : (
354	                        itens.map((it) => (
355	                          <TableRow key={it.id}>
356	                            <TableCell
357	                              className={isMobile ? 'text-xs p-1' : ''}
358	                            >
359	                              {it.nome_produto}
360	                            </TableCell>
361	                            <TableCell
362	                              className={isMobile ? 'text-xs p-1' : ''}
363	                            >
364	                              {it.lote || ''}
365	                            </TableCell>
366	                            <TableCell
367	                              className={isMobile ? 'text-xs p-1' : ''}
368	                            >
369	                              {it.validade || ''}
370	                            </TableCell>
371	                            <TableCell
372	                              className={`font-medium ${isMobile ? 'text-xs p-1' : ''}`}
373	                            >
374	                              {it.quantidade_solicitada}
375	                            </TableCell>
376	                            <TableCell
377	                              className={isMobile ? 'text-xs p-1' : ''}
378	                            >
379	                              {it.quantidade_enviada || ''}
380	                            </TableCell>
381	                            <TableCell
382	                              className={isMobile ? 'text-xs p-1' : ''}
383	                            >
384	                              {it.observacao || ''}
385	                            </TableCell>
386	                          </TableRow>
387	                        ))
388	                      )}
389	                    </TableBody>
390	                  </Table>
391	                </div>
392	              </CardContent>
393	            </Card>
394	          </div>
395	        )}
396	      </DialogContent>
397	    </Dialog>
398	  );
399	};
400	
401	export default RequisicaoDetailsModal;
