1	/**
2	 * Universal HTML print utility with iOS Safari support.
3	 *
4	 * iOS Safari bugs when calling window.print() programmatically from a popup
5	 * opened via window.open(). Auto-print does not fire, and the resulting window
6	 * has no visible UI (no print button, no share, no back), trapping the user.
7	 *
8	 * Solution: detect iOS and inject a sticky visible toolbar with buttons the
9	 * user can actually tap (Imprimir/AirPrint, Compartilhar, Fechar). On
10	 * Android/Desktop, keep the existing silent auto-print behavior.
11	 */
12	
13	export function isIOS(): boolean {
14	  if (typeof navigator === 'undefined') return false;
15	  const ua = navigator.userAgent || '';
16	  // iPadOS 13+ reports as MacIntel — detect via maxTouchPoints
17	  return (
18	    /iPad|iPhone|iPod/.test(ua) ||
19	    (navigator.platform === 'MacIntel' && (navigator as any).maxTouchPoints > 1)
20	  );
21	}
22	
23	const IOS_TOOLBAR_CSS = `
24	  <style>
25	    .momma-print-toolbar {
26	      position: sticky;
27	      top: 0;
28	      left: 0;
29	      right: 0;
30	      z-index: 999999;
31	      display: flex;
32	      gap: 8px;
33	      padding: 10px 12px;
34	      padding-top: max(10px, env(safe-area-inset-top));
35	      background: #ffffff;
36	      border-bottom: 1px solid #e5e7eb;
37	      box-shadow: 0 2px 8px rgba(0,0,0,0.08);
38	      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
39	    }
40	    .momma-print-toolbar button {
41	      flex: 1;
42	      min-height: 44px;
43	      padding: 10px 14px;
44	      border-radius: 10px;
45	      border: none;
46	      font-size: 15px;
47	      font-weight: 600;
48	      cursor: pointer;
49	      -webkit-tap-highlight-color: transparent;
50	      display: inline-flex;
51	      align-items: center;
52	      justify-content: center;
53	      gap: 6px;
54	    }
55	    .momma-print-toolbar button.primary {
56	      background: #57715B;
57	      color: #fff;
58	    }
59	    .momma-print-toolbar button.primary:active { background: #465b49; }
60	    .momma-print-toolbar button.secondary {
61	      background: #f3f4f6;
62	      color: #111827;
63	    }
64	    .momma-print-toolbar button.secondary:active { background: #e5e7eb; }
65	    .momma-print-toolbar button.ghost {
66	      background: transparent;
67	      color: #6b7280;
68	      flex: 0 0 auto;
69	      min-width: 44px;
70	    }
71	    .momma-print-toolbar button.ghost:active { background: #f3f4f6; }
72	    @media print {
73	      .momma-print-toolbar { display: none !important; }
74	    }
75	  </style>
76	`;
77	
78	const IOS_TOOLBAR_HTML = `
79	  <div class="momma-print-toolbar" role="toolbar" aria-label="Ações">
80	    <button type="button" class="ghost" onclick="window.history.length>1?window.history.back():window.close()" aria-label="Voltar">
81	      &larr;
82	    </button>
83	    <button type="button" class="primary" onclick="window.print()" aria-label="Imprimir">
84	      🖨️ Imprimir
85	    </button>
86	    <button type="button" class="secondary" id="momma-share-btn" aria-label="Compartilhar" style="display:none">
87	      📤 Compartilhar
88	    </button>
89	    <button type="button" class="ghost" onclick="window.close()" aria-label="Fechar">
90	      ✕
91	    </button>
92	  </div>
93	  <script>
94	    (function() {
95	      // Enable Web Share API if available
96	      if (navigator.share) {
97	        var btn = document.getElementById('momma-share-btn');
98	        if (btn) {
99	          btn.style.display = 'inline-flex';
100	          btn.addEventListener('click', function() {
101	            navigator.share({
102	              title: document.title,
103	              text: document.title,
104	              url: window.location.href
105	            }).catch(function(){});
106	          });
107	        }
108	      }
109	    })();
110	  </script>
111	`;
112	
113	/**
114	 * Open an HTML document in a new window/tab and trigger print.
115	 * On iOS: injects a visible toolbar (no auto-print — user taps Imprimir).
116	 * On Android/Desktop: silent auto-print after onload.
117	 *
118	 * The provided html should be a full HTML document (with <html><head><body>).
119	 * If it's a fragment, we'll wrap it.
120	 */
121	export function printHTML(html: string, options?: { title?: string }) {
122	  const title = options?.title || 'Impressão';
123	  const iOS = isIOS();
124	
125	  // Wrap fragment as full document if needed
126	  let fullHTML = html;
127	  const hasHtmlTag = /<html[\s>]/i.test(html);
128	  if (!hasHtmlTag) {
129	    fullHTML = `<!DOCTYPE html>
130	<html lang="pt-BR">
131	<head>
132	<meta charset="UTF-8">
133	<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
134	<title>${escapeHTML(title)}</title>
135	</head>
136	<body>
137	${html}
138	</body>
139	</html>`;
140	  }
141	
142	  if (iOS) {
143	    fullHTML = injectIOSToolbar(fullHTML, title);
144	  }
145	
146	  const win = window.open('', '_blank');
147	  if (!win) {
148	    // Popup blocked — fallback: download as HTML file
149	    downloadAsHTML(fullHTML, title);
150	    return;
151	  }
152	
153	  win.document.open();
154	  win.document.write(fullHTML);
155	  win.document.close();
156	
157	  if (!iOS) {
158	    // Desktop/Android: auto-print after load
159	    const triggerPrint = () => {
160	      try {
161	        win.focus();
162	        win.print();
163	      } catch {}
164	    };
165	    if (win.document.readyState === 'complete') {
166	      setTimeout(triggerPrint, 250);
167	    } else {
168	      win.addEventListener('load', () => setTimeout(triggerPrint, 250));
169	    }
170	  }
171	}
172	
173	function injectIOSToolbar(fullHTML: string, title: string): string {
174	  // Inject CSS into <head>
175	  let out = fullHTML.replace(/<\/head>/i, `${IOS_TOOLBAR_CSS}</head>`);
176	  if (!/<\/head>/i.test(fullHTML)) {
177	    // No </head> — inject at start
178	    out = `${IOS_TOOLBAR_CSS}${out}`;
179	  }
180	  // Inject toolbar right after <body> opening tag
181	  out = out.replace(/<body([^>]*)>/i, `<body$1>${IOS_TOOLBAR_HTML}`);
182	  if (!/<body[\s>]/i.test(out)) {
183	    // No <body> — prepend toolbar
184	    out = `${IOS_TOOLBAR_HTML}${out}`;
185	  }
186	  // Ensure title
187	  if (!/<title>/i.test(out)) {
188	    out = out.replace(/<head>/i, `<head><title>${escapeHTML(title)}</title>`);
189	  }
190	  return out;
191	}
