193	function downloadAsHTML(html: string, title: string) {
194	  const blob = new Blob([html], { type: 'text/html;charset=utf-8' });
195	  const url = URL.createObjectURL(blob);
196	  const a = document.createElement('a');
197	  a.href = url;
198	  a.download = `${sanitizeFileName(title)}.html`;
199	  document.body.appendChild(a);
200	  a.click();
201	  document.body.removeChild(a);
202	  setTimeout(() => URL.revokeObjectURL(url), 1000);
203	}
